CREATE TABLE gis_map_document (id INTEGER PRIMARY KEY);
CREATE TABLE gis_map_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('null','boolean','unsigned','signed','float','text','bytes','array','object')));
CREATE TABLE gis_map_position (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES gis_map_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), feature_id TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES gis_map_value(id));
CREATE TABLE gis_map_route (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES gis_map_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), feature_id TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES gis_map_value(id));
CREATE TABLE gis_map_region (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES gis_map_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), feature_id TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES gis_map_value(id));
CREATE TABLE gis_map_drawing_child (id INTEGER PRIMARY KEY REFERENCES gis_map_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE gis_map_image_child (id INTEGER PRIMARY KEY REFERENCES gis_map_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE gis_map_value_child (id INTEGER PRIMARY KEY REFERENCES gis_map_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE gis_map_null (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id));
CREATE TABLE gis_map_boolean (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id), value INTEGER NOT NULL CHECK(value IN (0,1)));
CREATE TABLE gis_map_unsigned (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id), high INTEGER NOT NULL CHECK(high BETWEEN 0 AND 4294967295), low INTEGER NOT NULL CHECK(low BETWEEN 0 AND 4294967295));
CREATE TABLE gis_map_signed (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id), value INTEGER NOT NULL);
CREATE TABLE gis_map_float (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL CHECK(value_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE gis_map_text (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id), value TEXT NOT NULL);
CREATE TABLE gis_map_bytes (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id));
CREATE TABLE gis_map_octet (id INTEGER PRIMARY KEY, bytes_id INTEGER NOT NULL REFERENCES gis_map_bytes(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE gis_map_array (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id));
CREATE TABLE gis_map_array_element (id INTEGER PRIMARY KEY, array_id INTEGER NOT NULL REFERENCES gis_map_array(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value_id INTEGER NOT NULL REFERENCES gis_map_value(id));
CREATE TABLE gis_map_object (id INTEGER PRIMARY KEY REFERENCES gis_map_value(id));
CREATE TABLE gis_map_object_member (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES gis_map_object(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES gis_map_value(id));
